// Pre-generates responsive hero image variants at build time.
//
// vite-imagetools query directives (e.g. `?w=640&format=avif`) only run
// through Vite's plugin pipeline for JS-module imports — Vite's HTML
// resolver for `<img src>`/`srcset` never sends the query string through
// `resolveId`/`load`, so those directives are silent no-ops when written
// directly into index.html. Generating fixed-name files up front and
// referencing plain filenames in the srcset sidesteps that limitation.
//
// Output is gitignored and regenerated by the "prebuild" npm script.
import sharp from 'sharp';
import { mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SOURCE = path.join(__dirname, '../src/assets/profile_image_02.jpg');
const OUT_DIR = path.join(__dirname, '../src/assets/hero');

const WIDTHS = [640, 828, 1080, 1440, 1920, 2560];
const FORMATS = [
    { ext: 'avif', quality: 55 },
    { ext: 'webp', quality: 75 },
    { ext: 'jpg', quality: 75 },
];

if (!existsSync(SOURCE)) {
    console.error(`[generate-hero-variants] source image not found: ${SOURCE}`);
    process.exitCode = 1;
} else {
    await mkdir(OUT_DIR, { recursive: true });

    const jobs = WIDTHS.flatMap((width) =>
        FORMATS.map(async ({ ext, quality }) => {
            const outFile = path.join(OUT_DIR, `profile-${width}.${ext}`);
            let pipeline = sharp(SOURCE).resize({ width });
            pipeline = ext === 'jpg' ? pipeline.jpeg({ quality }) : pipeline[ext]({ quality });
            await pipeline.toFile(outFile);
        })
    );

    await Promise.all(jobs);
    console.log(`[generate-hero-variants] generated ${jobs.length} files in ${path.relative(process.cwd(), OUT_DIR)}/`);
}
